import{_ as a,c as n,a as i,o as r}from"./app-i2w7PHGN.js";const t={};function c(s,e){return r(),n("div",null,e[0]||(e[0]=[i('<blockquote><p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。 欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p></blockquote><h1 id="_2026-09-20-资讯日报" tabindex="-1"><a class="header-anchor" href="#_2026-09-20-资讯日报"><span>2026-09-20 资讯日报</span></a></h1><h2 id="新闻资讯" tabindex="-1"><a class="header-anchor" href="#新闻资讯"><span>新闻资讯</span></a></h2><h3 id="沈俊潇-视觉记忆驱动物理ai自进化" tabindex="-1"><a class="header-anchor" href="#沈俊潇-视觉记忆驱动物理ai自进化"><span>沈俊潇：视觉记忆驱动物理AI自进化</span></a></h3><p>沈俊潇：当前AI记忆分两类，个性化记忆护城河已快速消失，真正有价值的是靠视觉记忆帮物理AI实现递归自进化，解决物理AI标注痛点，Memories.ai已形成数据飞轮，只做数据与模型后训练。<a href="https://mp.weixin.qq.com/s?__biz=MzA3NTIyODUzNA==&amp;chksm=861fe5de84adf964cc56e9e565f4ecea4bcebacc573b8ae4e8a4047e358aedd273c67ef1e655&amp;idx=1&amp;mid=2649805825&amp;sn=3662255a265451f132f463d533e83925#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="国产大模型出海加速-minimax连签三单" tabindex="-1"><a class="header-anchor" href="#国产大模型出海加速-minimax连签三单"><span>国产大模型出海加速 MiniMax连签三单</span></a></h3><p>MiniMax半月连获三地海外订单，当前海外AI需求已分层：C端拼体验，API拼性价比稳定性，开源底座承接定制需求，中国大模型出海进入商业化能力比拼阶段。<a href="https://mp.weixin.qq.com/s?__biz=MzA5ODEzMjIyMA==&amp;chksm=9123485d95035982b7ece458a02fc41ec560ac1ea4f14a34b41714d7aba8d60013fea013e0a3&amp;idx=1&amp;mid=2247745860&amp;sn=503d4f2541030e71950681f5e998e3d0#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="前openai核心推出哑巴ai-jev爆火硅谷" tabindex="-1"><a class="header-anchor" href="#前openai核心推出哑巴ai-jev爆火硅谷"><span>前OpenAI核心推出哑巴AI Jev爆火硅谷</span></a></h3><p>前OpenAI核心成员Diogo Almeida认为，当前AI行业跑偏，错把“嘴”当成“脑子”，RLHF训练的聊天模型无法实现真自动化；他推出只做决策不生成文字的Jev，主打极速廉价零幻觉，引爆硅谷开发者圈。<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f0110af3c1ccfa4d219a9537761b0b01030df557c41df5d66613cfa4ca2449071723e0699e11&amp;idx=1&amp;mid=2652727724&amp;sn=7f610b717066d7a38a97246e745cc601#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="推荐文章" tabindex="-1"><a class="header-anchor" href="#推荐文章"><span>推荐文章</span></a></h2><h3 id="阶跃step-5-没赢gpt却更好用" tabindex="-1"><a class="header-anchor" href="#阶跃step-5-没赢gpt却更好用"><span>阶跃Step 5：没赢GPT却更好用</span></a></h3><p>作者实测：Step 5 Preview写码能力接近GPT-5.6 Sol，token消耗更低、出活更稳定，幻觉控制优于多数国产模型，虽没赢GPT，日常使用反而更好用。<a href="https://mp.weixin.qq.com/s?__biz=MzkxNjcyNTk2NA==&amp;chksm=c092de40bf135d98291c16eeb2d1e21b1091e8777911050700fb084c53098ef9b30c136a1829&amp;idx=1&amp;mid=2247494425&amp;sn=31d610f7c15a86b6b676e60535e06cc4#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="开源动态" tabindex="-1"><a class="header-anchor" href="#开源动态"><span>开源动态</span></a></h2><h3 id="开源3天7-1k-star-jev加持浏览器agent" tabindex="-1"><a class="header-anchor" href="#开源3天7-1k-star-jev加持浏览器agent"><span>开源3天7.1k Star Jev加持浏览器Agent</span></a></h3><p>Browser-Use团队推出的jev-ultrafast整合Jev模型到浏览器Agent，采用读DOM替代截图推理，比传统方案提速25%，调用次数降91%，单次任务成本不到3厘钱，范式创新加速落地。<a href="https://mp.weixin.qq.com/s?__biz=MzkwMjQ0NzI0OQ==&amp;chksm=c18295a0ab3878169fc54f12a2f73f1f6c481514efb1dab31350b2821a6b64a4c4b26c47af0a&amp;idx=1&amp;mid=2247507002&amp;sn=b622c17fadc47fd33c6a5dbb589e0b44#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="算法论文" tabindex="-1"><a class="header-anchor" href="#算法论文"><span>算法论文</span></a></h2><h3 id="多校推出vbvr-pro视觉推理训练场" tabindex="-1"><a class="header-anchor" href="#多校推出vbvr-pro视觉推理训练场"><span>多校推出VBVR-Pro视觉推理训练场</span></a></h3><p>NTU等多校联合团队推出VBVR-Pro，打造含300项任务的视觉推理训练场，搭配可验证打分器，可作为强化学习奖励提升模型能力，跨场景任务性能最高提升超20个百分点。<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=856a4e391dea6eacd76b7d9b840782008ece4d374b1d0355d1cb3b0695cfd1de606de3398fcc&amp;idx=2&amp;mid=2651058613&amp;sn=a6bafeb30abb2a0e52f221d7822c4965#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><p style="text-align:center;"><img id="weixin_qr" src="https://meikan-public-images.oss-cn-beijing.aliyuncs.com/imeikan/assets/2025-05-18234303-hub.png" style="max-width:800px;object-fit:cover;"></p><p><a href="https://aireadinghub.com/" target="_blank" rel="noopener noreferrer">官网：www.AiReadingHub.com</a></p>',20)]))}const d=a(t,[["render",c]]),l=JSON.parse('{"path":"/posts/2026-09-20.html","title":"AI日报：沈俊潇：视觉记忆驱动物理AI自进化; 国产大模型出海加速 MiniMax连签三单; 前OpenAI核心推出哑巴AI Jev爆火硅谷","lang":"zh-CN","frontmatter":{"date":"2026-09-20T00:00:00.000Z","title":"AI日报：沈俊潇：视觉记忆驱动物理AI自进化; 国产大模型出海加速 MiniMax连签三单; 前OpenAI核心推出哑巴AI Jev爆火硅谷"},"headers":[{"level":2,"title":"新闻资讯","slug":"新闻资讯","link":"#新闻资讯","children":[{"level":3,"title":"沈俊潇：视觉记忆驱动物理AI自进化","slug":"沈俊潇-视觉记忆驱动物理ai自进化","link":"#沈俊潇-视觉记忆驱动物理ai自进化","children":[]},{"level":3,"title":"国产大模型出海加速 MiniMax连签三单","slug":"国产大模型出海加速-minimax连签三单","link":"#国产大模型出海加速-minimax连签三单","children":[]},{"level":3,"title":"前OpenAI核心推出哑巴AI Jev爆火硅谷","slug":"前openai核心推出哑巴ai-jev爆火硅谷","link":"#前openai核心推出哑巴ai-jev爆火硅谷","children":[]}]},{"level":2,"title":"推荐文章","slug":"推荐文章","link":"#推荐文章","children":[{"level":3,"title":"阶跃Step 5：没赢GPT却更好用","slug":"阶跃step-5-没赢gpt却更好用","link":"#阶跃step-5-没赢gpt却更好用","children":[]}]},{"level":2,"title":"开源动态","slug":"开源动态","link":"#开源动态","children":[{"level":3,"title":"开源3天7.1k Star Jev加持浏览器Agent","slug":"开源3天7-1k-star-jev加持浏览器agent","link":"#开源3天7-1k-star-jev加持浏览器agent","children":[]}]},{"level":2,"title":"算法论文","slug":"算法论文","link":"#算法论文","children":[{"level":3,"title":"多校推出VBVR-Pro视觉推理训练场","slug":"多校推出vbvr-pro视觉推理训练场","link":"#多校推出vbvr-pro视觉推理训练场","children":[]}]}],"git":{"updatedTime":1790328069000,"contributors":[{"name":"GitHub Actions","username":"","email":"actions@github.com","commits":1}],"changelog":[{"hash":"1b8b1a93db4d96898235bbb08061fc22765f52ec","time":1790328069000,"email":"actions@github.com","author":"GitHub Actions","message":"Auto-commit generated files on 2026-09-25T09:21:09.962Z"}]},"filePathRelative":"posts/2026-09-20.md","excerpt":"<blockquote>\\n<p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。\\n欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p>\\n</blockquote>\\n<h1>2026-09-20 资讯日报</h1>\\n<h2>新闻资讯</h2>\\n<h3>沈俊潇：视觉记忆驱动物理AI自进化</h3>\\n<p>沈俊潇：当前AI记忆分两类，个性化记忆护城河已快速消失，真正有价值的是靠视觉记忆帮物理AI实现递归自进化，解决物理AI标注痛点，Memories.ai已形成数据飞轮，只做数据与模型后训练。<a href=\\"https://mp.weixin.qq.com/s?__biz=MzA3NTIyODUzNA==&amp;chksm=861fe5de84adf964cc56e9e565f4ecea4bcebacc573b8ae4e8a4047e358aedd273c67ef1e655&amp;idx=1&amp;mid=2649805825&amp;sn=3662255a265451f132f463d533e83925#rd\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">&gt;阅读原文</a></p>"}');export{d as comp,l as data};
